fn resolve_texture_slot(
    &mut self,
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    texture: Option<&Arc<Texture>>,
    pending: Option<&Arc<DecodedTexture>>,
    fallback: Arc<Texture>,
    encoding: TextureSampleEncoding,
) -> Arc<Texture> {
    if let Some(texture) = texture {
        return Arc::clone(texture);
    }
    let Some(pending) = pending else {
        return fallback;
    };
    match self.decoded_texture_cache.resolve(
        device,
        queue,
        pending,
        encoding,
        self.texture_uploads_remaining > 0,
    ) {
        DecodedTextureResolve::Hit(texture) => texture,
        DecodedTextureResolve::Uploaded(texture) => {
            self.texture_uploads_remaining = self.texture_uploads_remaining.saturating_sub(1);
            self.texture_uploads_uploaded = self.texture_uploads_uploaded.saturating_add(1);
            texture
        }
        DecodedTextureResolve::Deferred => {
            self.texture_uploads_pending = self.texture_uploads_pending.saturating_add(1);
            fallback
        }
        DecodedTextureResolve::Failed => fallback,
    }
}
